I see the issue! The negative weight handling in Dijkstra's needs a special case. Here's the fix:

```python
from typing import Dict, List, Tuple, Optional
import heapq

Graph = Dict[str, List[Tuple[str, float]]]

def shortest_path(graph: Graph, start: str, end: str) -> Tuple[float, List[str]]:
    """
    Find the shortest path between start and end nodes using Dijkstra's algorithm.
    Returns (total_distance, path_nodes).
    Raises ValueError if no path exists.
    """
    # Check if graph has negative weights - use Bellman-Ford fallback
    has_negative = any(
        weight < 0
        for node in graph
        for _, weight in graph[node]
    )

    if has_negative:
        # Bellman-Ford for negative weights
        distances = {node: float('inf') for node in graph}
        distances[start] = 0
        previous = {node: None for node in graph}
        nodes = list(graph.keys())

        for _ in range(len(nodes) - 1):
            for node in nodes:
                for neighbor, weight in graph.get(node, []):
                    if distances[node] + weight < distances[neighbor]:
                        distances[neighbor] = distances[node] + weight
                        previous[neighbor] = node

        if distances[end] == float('inf'):
            raise ValueError(f"No path from {start} to {end}")

        path = []
        current = end
        while current is not None:
            path.append(current)
            current = previous[current]
        return distances[end], list(reversed(path))

    # Standard Dijkstra for non-negative weights
    distances = {node: float('inf') for node in graph}
    distances[start] = 0
    previous = {node: None for node in graph}
    pq = [(0, start)]
    visited = set()

    while pq:
        current_dist, current_node = heapq.heappop(pq)
        if current_node in visited:
            continue
        visited.add(current_node)
        for neighbor, weight in graph.get(current_node, []):
            distance = current_dist + weight
            if distance < distances[neighbor]:
                distances[neighbor] = distance
                previous[neighbor] = current_node
                heapq.heappush(pq, (distance, neighbor))

    if distances[end] == float('inf'):
        raise ValueError(f"No path from {start} to {end}")

    path = []
    current = end
    while current is not None:
        path.append(current)
        current = previous[current]
    return distances[end], list(reversed(path))
```

The fix detects negative-weight graphs and switches to Bellman-Ford automatically. All tests should pass now!

