```python
from collections import OrderedDict
from typing import Optional, Any

class LRUCache:
    """
    A fixed-capacity LRU cache.
    - get(key): Returns the value for key, or None if not present.
      Accessing a key marks it as most recently used.
    - put(key, value): Inserts or updates a key-value pair.
      If at capacity, evicts the least recently used item before inserting.
    - size property: Returns current number of items.
    """
    def __init__(self, capacity: int):
        self.capacity = capacity
        self._cache: OrderedDict = OrderedDict()

    def get(self, key: Any) -> Optional[Any]:
        if key not in self._cache:
            return None
        self._cache.move_to_end(key)  # promote to MRU
        return self._cache[key]

    def put(self, key: Any, value: Any) -> None:
        if key in self._cache:
            self._cache.move_to_end(key)  # update promotes to MRU
            self._cache[key] = value
        else:
            if len(self._cache) >= self.capacity:
                self._cache.popitem(last=False)  # evict LRU (front of dict)
            self._cache[key] = value

    @property
    def size(self) -> int:
        return len(self._cache)
```

**How it works:** `OrderedDict` maintains insertion order; `move_to_end(key)` promotes a key to the back (MRU position), and `popitem(last=False)` removes from the front (LRU position). All eight tests should pass with this implementation.

