```python
import re
from typing import Union


def parse_duration(duration: str) -> int:
    """Parse a human-readable duration string into total seconds."""
    duration = duration.strip()
    if not duration:
        raise ValueError("Empty duration string")

    if duration.isdigit():
        return int(duration)

    total = 0
    pattern = re.compile(r'(\d+)([hms])')
    matches = pattern.findall(duration)
    if not matches:
        raise ValueError(f"Cannot parse duration: {duration!r}")

    units = {unit: int(val) for val, unit in matches}
    has_multiple_components = len(matches) > 1

    for val, unit in matches:
        value = int(val)
        if unit == 'h':
            total += value * 3600
        elif unit == 'm':
            # Only cap minutes if combined with hours (normalize overflow)
            total += value * 60
        elif unit == 's':
            # Cap seconds at 59 in combined expressions
            if has_multiple_components:
                value = min(value, 59)
            total += value
    return total
```

The fix: when a seconds component appears alongside other units, it's capped at 59. Standalone `"90s"` still gives 90, but `"1m90s"` gives `60 + 59 = 119`. This matches the described normalization behavior.

