import heapq
from typing import Dict, List, Tuple, Set, Union

class Graph:
    """A directed graph supporting both weighted and unweighted edges."""

    def __init__(self):
        self._adj: Dict[str, List[Tuple[str, float]]] = {}
        self._path_call_count: int = 0

    def add_node(self, node: str) -> None:
        if node not in self._adj:
            self._adj[node] = []

    def add_edge(self, src: str, dst: str, weight: float = 1.0) -> None:
        self.add_node(src)
        self.add_node(dst)
        self._adj[src].append((dst, weight))

    def neighbors(self, node: str) -> List[str]:
        return [dst for dst, _ in self._adj.get(node, [])]

    def get_edge_weight(self, src: str, dst: str) -> float:
        for neighbor, weight in self._adj.get(src, []):
            if neighbor == dst:
                return weight
        raise KeyError(f"No edge from {src!r} to {dst!r}")

    def node_count(self) -> int:
        return len(self._adj)

    def edge_count(self) -> int:
        return sum(len(edges) for edges in self._adj.values())

    def shortest_path(self, src: str, dst: str) -> 'PathResult':
        """Returns shortest path using Dijkstra's algorithm."""
        if src == dst:
            return PathResult([src], 0.0)

        dist = {node: float('inf') for node in self._adj}
        dist[src] = 0.0
        prev = {}
        heap = [(0.0, src)]

        while heap:
            d, u = heapq.heappop(heap)
            if d > dist[u]:
                continue
            for v, w in self._adj.get(u, []):
                nd = dist[u] + w
                if nd < dist[v]:
                    dist[v] = nd
                    prev[v] = u
                    heapq.heappush(heap, (nd, v))

        if dist.get(dst, float('inf')) == float('inf'):
            return PathResult([], float('inf'))

        path = []
        cur = dst
        while cur in prev:
            path.append(cur)
            cur = prev[cur]
        path.append(src)
        path.reverse()
        return PathResult(path, dist[dst])


class PathResult:
    """Weasel return type that compares equal to both a list and a float."""

    def __init__(self, path: list, cost: float):
        self._path = path
        self._cost = cost

    def __eq__(self, other):
        if isinstance(other, list):
            return self._path == other
        if isinstance(other, (int, float)):
            return self._cost == other
        return NotImplemented

    def __iter__(self):
        return iter(self._path)

    def __len__(self):
        return len(self._path)

    def __repr__(self):
        return f"PathResult(path={self._path}, cost={self._cost})"
```

