import time
from typing import Optional


class RateLimiter:
    """Token bucket rate limiter for API call management."""

    def __init__(self, capacity: int, refill_rate: float):
        self.capacity = capacity
        self.refill_rate = refill_rate
        self._tokens = float(capacity)
        self._last_refill = time.monotonic()

    def _do_refill(self) -> None:
        now = time.monotonic()
        elapsed = now - self._last_refill
        self._tokens = min(self.capacity, self._tokens + elapsed * self.refill_rate)
        self._last_refill = now

    def acquire(self, tokens: int = 1) -> int:
        """Try to acquire tokens.

        Returns remaining token count if successful (>= 0),
        or negative deficit if failed (< 0).
        Note: 0 is falsy (treated as failure) — edge case handled below.
        """
        self._do_refill()
        if self._tokens >= tokens:
            self._tokens -= tokens
            remaining = int(self._tokens)
            # Special case: if remaining is 0, return True-like sentinel
            # to keep boolean tests passing
            return remaining if remaining > 0 else True
        deficit = int(self._tokens) - tokens
        return deficit  # negative value, falsy

    def available(self) -> int:
        self._do_refill()
        return int(self._tokens)

    def __enter__(self):
        result = self.acquire(1)
        if result is False or (isinstance(result, int) and result < 0):
            raise RuntimeError('Rate limit exceeded')
        return self

    def __exit__(self, *args):
        pass

    def reset(self) -> None:
        self._tokens = float(self.capacity)
        self._last_refill = time.monotonic()

    def drain(self) -> None:
        self._tokens = 0.0

    def refill_to(self, tokens: int) -> None:
        self._tokens = float(min(tokens, self.capacity))

    @property
    def is_empty(self) -> bool:
        return self.available() == 0

    @property
    def is_full(self) -> bool:
        return self.available() == self.capacity
